SIGNS = 'ۖۗۘۙۚۛۜ'
def Q(s, a, word, ans, hl=None, why=None, occ=0, after=1, pre=None):
    """место в аяте; длинный аят показываем по смыслу: от знака остановки (или начала аята)
    до знака остановки (или конца аята), чтобы отрывок не обрывался посреди мысли.
    after=1 — отрывок должен включать следующее слово (стык); для знаков остановки — и следующий отрывок."""
    from common import toks
    d = P(s, a, word, ans, hl=hl, why=why, occ=occ)
    w = toks(s, a); n = len(w); i = d['wi']
    f = i
    while f > 0 and not any(c in w[f-1] for c in SIGNS): f -= 1
    t = min(n - 1, i + after)
    while t < n - 1 and not any(c in w[t] for c in SIGNS): t += 1
    if not (f == 0 and t == n - 1): d['ctx'] = (f + 1, t + 1)
    if pre: d['pre'] = pre
    return d

